(() => {
 const m=x=>(x<0?'−':'')+'£'+Math.abs(x).toFixed(2)+'m',p=x=>(100*x).toFixed(1)+'%',sum=a=>a.reduce((s,x)=>s+x,0),a=(id,label,min,max,step,value,unit='£m')=>({id,label,min,max,step,value,unit}),sel=(id,label,options,value)=>({id,label,options,value});
 const R={pra:['https://www.bankofengland.co.uk/prudential-regulation/publication/2015/the-pras-approach-to-supervising-liquidity-and-funding-risks-ss','PRA SS24/15 · liquidity and funding supervision'],liq:['https://www.bis.org/committees/bcbs/basel-consolidated-guidelines/module/lqy/10','Basel · sound liquidity risk management'],lcr:['https://www.bis.org/committees/bcbs/basel-framework/standard/lcr?allChapters=true','Basel · LCR framework'],nsfr:['https://www.bis.org/committees/bcbs/basel-framework/standard/nsf?allChapters=true','Basel · NSFR framework'],ir:['https://www.bis.org/committees/bcbs/basel-framework/standard/srp/31/inforce/2026-01-01/published/2024-07-16','Basel · interest rate risk in the banking book'],fx:['https://www.bis.org/committees/bcbs/basel-consolidated-guidelines/module/rma/20','Basel · foreign exchange settlement risks'],intra:['https://www.bis.org/publications/201304-standards-monitoring-tools-intraday-liquidity-management','Basel · intraday liquidity monitoring'],boe:['https://www.bankofengland.co.uk/markets/bank-of-england-market-operations-guide','Bank of England · Market Operations Guide']};
 const out=(labels,values,rows,explanation,stats)=>({stats:stats||labels.slice(0,3).map((l,i)=>[l,m(values[i])]),bars:labels.map((label,i)=>({label,value:values[i],color:['#285e46','#779db0','#b68744','#93b77b'][i%4]})),headers:['Quantity','Value','Interpretation'],rows,explanation});
 const path=(cash,daily,days=30)=>Array.from({length:days+1},(_,i)=>[i,cash-i*daily]);
 window.TRISK_LESSONS=[];
 const add=l=>TRISK_LESSONS.push({simpleTitle:'The idea, in plain language',chart:'See the decision and its consequences',key:'All portfolios, shocks, behavioural parameters and internal limits are synthetic teaching assumptions unless explicitly stated. Amounts are £m; rates shown as percentages are divided by 100 in calculations.',sources:[R.liq,R.pra],notes:[],...l});
 window.TRISK_UI={m,p,sum,a,sel,out,path,R,add};
 add({id:'balance-sheet',stage:'01 · How treasury works',name:'Build a bank balance sheet',title:'Treasury connects the assets a bank owns to the funding it needs.',intro:'Build a simple bank and see the residual funding requirement and annual net interest income.',inputs:[a('loans','Customer loans',300,1000,25,700),a('bonds','Liquid securities',20,200,10,100),a('cash','Cash reserves',10,150,10,20),a('deposits','Customer deposits',200,700,25,650)],challenge:'Grow loans without attracting deposits. Where does the funding come from?',formula:'Assets = loans + securities + cash\nFunding gap = assets − deposits − equity\nNII = asset interest − deposit interest − wholesale interest',simple:'A bank’s loans may repay over years while customers can withdraw deposits today. Treasury manages that mismatch, keeps payments flowing, sources funding and manages financial risks. Profitability, capital and cash availability must all be considered.',scope:'Equity fixed at £70m. Positive gap is wholesale borrowing at 4.5%; negative gap is excess funding invested in overnight cash at 3%. Loans yield 6%, bonds 4%, cash 3%, deposits cost 2%. No fees, operating costs, impairment or tax.',compute(s){const gap=s.loans+s.bonds+s.cash-s.deposits-70,nii=s.loans*.06+s.bonds*.04+(s.cash+Math.max(-gap,0))*.03-s.deposits*.02-Math.max(gap,0)*.045;return out(['Assets','Wholesale need','Annual NII'],[s.loans+s.bonds+s.cash+Math.max(-gap,0),Math.max(gap,0),nii],[['Equity',m(70),'Loss-absorbing funding, not a cash pot'],['Excess overnight investment',m(Math.max(-gap,0)),'Balances the sheet if deposits exceed initial assets'],['Net interest income',m(nii),'Before all other income and expenses']],`The balance sheet needs ${m(Math.max(gap,0))} of wholesale funding. Growing profitable loans can still consume liquidity.`);}});
 add({id:'solvency',stage:'01 · How treasury works',name:'Liquidity versus solvency',title:'A solvent bank can run out of spendable cash.',intro:'Compare equity after an asset loss with cash after withdrawals.',inputs:[a('equity','Starting equity',10,100,5,60),a('cash','Available cash',5,100,5,30),a('loss','Recognised asset loss',0,100,5,20),a('withdraw','Deposit withdrawals',0,100,5,40)],challenge:'Create positive equity and negative cash headroom. What problem needs fixing?',formula:'Remaining equity = equity − recognised loss\nCash headroom = cash − withdrawals',simple:'Solvency is about whether assets can cover liabilities. Liquidity is about having usable funds when payments are due. Selling assets urgently can turn a liquidity problem into a capital problem if the sale crystallises losses.',scope:'Loss is non-cash in this snapshot; withdrawals reduce both cash and deposit liabilities equally. No new funding or asset sales. Negative headroom is an unmet payment need, not an actual negative bank account.',compute(s){const eq=s.equity-s.loss,c=s.cash-s.withdraw;return out(['Remaining equity','Cash headroom'],[eq,c],[['Solvency diagnostic',eq>0?'Positive equity':'Equity exhausted','Book-value simplification'],['Liquidity diagnostic',c>=0?'Cash covers withdrawals':'Funding action needed','Payment timing matters']],`${eq>0?'Equity remains positive':'Equity is exhausted'}, while ${c>=0?'cash covers withdrawals':'withdrawals exceed available cash'}. These are different diagnoses requiring different actions.`);}});
 add({id:'cash-forecast',stage:'01 · How treasury works',name:'Cash forecasting and uncertainty',title:'A cash forecast is a range of possible payment needs.',intro:'Project daily cash using expected receipts, payments and a stressed receipt shortfall.',inputs:[a('cash','Opening cash',10,100,5,50),a('inflow','Daily expected receipts',0,10,.5,4),a('outflow','Daily payments',0,10,.5,5),a('miss','Receipt shortfall under stress',0,100,5,30,'%')],challenge:'Leave payments unchanged and make some receipts fail to arrive.',formula:'Cash(t) = opening cash + t × (receipts − payments)\nStress receipts = expected receipts × (1−shortfall%)',simple:'Expected receipts cannot pay an obligation until they arrive. Treasury forecasts by date, currency and legal entity, reconciles actuals to forecasts and tests which assumptions are most fragile.',scope:'30 daily steps, constant flows, no weekend/calendar effects, funding actions or interest. Negative balances indicate funding gaps. This is a teaching cash ladder, not an LCR calculation.',compute(s){const base=s.outflow-s.inflow,stress=s.outflow-s.inflow*(1-s.miss/100),b=path(s.cash,base),v=path(s.cash,stress),breach=v.find(x=>x[1]<0);return {stats:[['Base day 30',m(b[30][1])],['Stress day 30',m(v[30][1])],['First stressed gap',breach?'Day '+breach[0]:'None within 30 days']],series:[{name:'Expected cash',color:'#285e46',data:b},{name:'Stressed receipts',color:'#b68744',data:v}],xlabel:'Day',headers:['Day','Expected cash','Stressed cash'],rows:[0,5,10,20,30].map(i=>[i,m(b[i][1]),m(v[i][1])]),explanation:`A ${s.miss}% receipt shortfall changes daily net cash use from ${m(base)} to ${m(stress)}. ${breach?'The first funding gap occurs on day '+breach[0]+'.':'No gap occurs in this 30-day window.'}`};}});
 add({id:'maturity-wall',stage:'02 · Funding and customer behaviour',name:'Maturity ladders and rollover',title:'A funding wall can arrive before your assets repay.',intro:'Place wholesale maturities into three dates and refinance a chosen fraction.',inputs:[a('cash','Opening cash',10,100,5,40),a('debt','Wholesale debt maturing',0,180,10,90),a('front','Share due in first period',0,100,5,60,'%'),a('roll','Successful refinancing share',0,100,5,50,'%')],challenge:'Keep total debt fixed but bring more maturities into the first period.',formula:'Unrefinanced maturity = debt due × (1−rollover fraction)\nClosing cash = prior cash + asset receipts − unrefinanced maturity',simple:'A balanced annual funding plan can hide a dangerous weekly or monthly cliff. Diversifying maturity dates gives treasury more time and more market opportunities to replace debt.',scope:'Periods represent months 1, 2 and 3; £10m asset receipts in each. Remaining debt split equally between periods 2 and 3. Refinance at maturity with no delay or cost. Beyond month 3 not modelled.',compute(s){const due=[s.debt*s.front/100,...Array(2).fill(s.debt*(1-s.front/100)/2)];let c=s.cash;const cash=due.map(d=>c+=10-d*(1-s.roll/100));return out(['Month 1 cash','Month 2 cash','Month 3 cash'],cash,due.map((d,i)=>['Month '+(i+1),m(d),'Debt due; '+m(d*(1-s.roll/100))+' not rolled']),`Earliest-period cash is ${m(cash[0])}. Equal total maturities do not imply equal short-term liquidity risk.`);}});
 add({id:'deposits',stage:'02 · Funding and customer behaviour',name:'Deposit stability and runoff',title:'A deposit balance is only as reliable as its behaviour under stress.',intro:'Split funding between a stable retail segment and a more rate-sensitive or concentrated segment.',inputs:[a('total','Deposit balance',100,1000,50,500),a('stable','Stable segment share',0,100,5,70,'%'),a('run1','Stable segment runoff',0,30,1,5,'%'),a('run2','Sensitive segment runoff',0,100,5,40,'%')],challenge:'Keep total deposits fixed and change the mix. Why does stressed outflow move?',formula:'Outflow = stable deposits × runoff1 + sensitive deposits × runoff2',simple:'Customers differ in insurance coverage, relationship strength, operational needs and ability to move funds quickly. Treasury segments deposits, examines observed behaviour and challenges assumptions under institution-specific and market-wide stress.',scope:'Two synthetic behavioural segments. Labels do not certify Basel LCR categories; runoff sliders are internal scenario assumptions, not prescribed rates. No inflows or feedback from deposit pricing.',compute(s){const d1=s.total*s.stable/100,d2=s.total-d1,o1=d1*s.run1/100,o2=d2*s.run2/100;return out(['Stable outflow','Sensitive outflow','Total outflow'],[o1,o2,o1+o2],[['Stable balance',m(d1),'Relationship assumptions need evidence'],['Sensitive balance',m(d2),'Insurance and concentration can matter'],['Retained funding',m(s.total-o1-o2),'After one selected stress window']],`The same ${m(s.total)} deposit base produces ${m(o1+o2)} of outflow under this mix. Total deposit size alone is not a stability measure.`);}});
 add({id:'deposit-beta',stage:'02 · Funding and customer behaviour',name:'Deposit beta, lag and migration',title:'Customer pricing can reprice slower than market rates—and then catch up.',intro:'Compare deposit interest cost before and after a market-rate move with partial pass-through and a repricing lag.',inputs:[a('balance','Deposit balance',100,1000,50,500),a('shock','Market-rate change',-2,4,.25,2,'percentage points'),a('beta','Deposit pass-through',0,100,5,40,'%'),a('lag','Months before repricing',0,12,1,3,'months')],challenge:'Increase beta and shorten the lag. What happens to annual funding cost?',formula:'New deposit rate = max(0, 2% + beta × market-rate change)\nAnnual cost = balance × [old rate × lag/12 + new rate × (12−lag)/12]',simple:'Deposit beta is the fraction of a market-rate move passed to customers. Lag controls timing. Customers may also move from low-rate current accounts to higher-rate products, so historical beta can understate future cost when behaviour changes.',scope:'Opening rate 2%, zero floor, immediate jump after selected lag, unchanged balances. No explicit product migration; that risk is discussed rather than calculated. Beta is not the same as deposit runoff or effective duration.',sources:[R.ir,R.liq],compute(s){const r=Math.max(0,.02+s.shock/100*s.beta/100),cost=s.balance*(.02*s.lag/12+r*(12-s.lag)/12),old=s.balance*.02;return out(['Original cost','New annual cost','Cost change'],[old,cost,cost-old],[['New deposit rate',p(r),'Zero floor applied'],['Lag',s.lag+' months','Old rate applies during the lag'],['Long-run annual cost',m(s.balance*r),'Full year at the new rate']],`Year-one funding cost changes by ${m(cost-old)}; the full run-rate cost can be larger when repricing is delayed.`);}});
 add({id:'concentration',stage:'02 · Funding and customer behaviour',name:'Funding concentration',title:'Many accounts can still depend on one source of confidence.',intro:'Allocate a deposit pool between one large provider and equally sized other providers.',inputs:[a('total','Funding balance',100,1000,50,500),a('share','Designated provider share',0,90,5,30,'%'),a('others','Other providers',1,50,1,20,'providers'),a('run','Designated provider withdrawal',0,100,5,100,'%')],challenge:'Increase the number of small providers while keeping the large provider unchanged.',formula:'HHI = large share² + (1−large share)² / other count\nWithdrawal = total × large share × runoff',simple:'Diversification should be examined by beneficial owner, sector, geography, channel, currency and maturity. A hundred accounts controlled by one treasury team are not a hundred independent funding decisions.',scope:'Equal other providers, one designated provider and no common-sector contagion. HHI measures size concentration, not the probability of a bank run. The designated provider need not be the largest at every setting.',compute(s){const w=s.share/100,h=w*w+(1-w)**2/s.others,o=s.total*w*s.run/100;return out(['Designated source','Other sources','Stress withdrawal'],[s.total*w,s.total*(1-w),o],[['HHI',h.toFixed(3),'Higher means more concentrated'],['Effective equal sources',(1/h).toFixed(1),'Reciprocal HHI'],['Stress withdrawal',m(o),'Single-provider scenario']],`The designated source can withdraw ${m(o)}. Adding small accounts does not remove that exposure.`,[['HHI',h.toFixed(3)],['Effective sources',(1/h).toFixed(1)],['Withdrawal',m(o)]]);}});
 add({id:'term-funding',stage:'02 · Funding and customer behaviour',name:'Term funding versus short funding',title:'Cheaper funding today can buy a larger refinancing problem tomorrow.',intro:'Compare a one-year term issue with funding that reprices halfway through the year.',inputs:[a('amount','Funding amount',10,500,10,100),a('short','Initial short rate',0,10,.25,4,'%'),a('term','One-year term rate',0,10,.25,5,'%'),a('future','Refinancing rate in six months',0,20,.5,8,'%')],challenge:'Find the future short rate at which term funding becomes cheaper.',formula:'Short strategy cost = amount × (initial rate + future rate)/2\nTerm strategy cost = amount × term rate',simple:'Term debt pays a premium for certainty over the funding period. Short debt can be cheaper in benign markets but must be renewed at an uncertain price and may not be available at all in stress.',scope:'Simple annual interest, two equal half-years, full successful rollover, no issuance fees or optional redemption. The separate maturity lesson models rollover failure.',compute(s){const sh=s.amount*(s.short+s.future)/200,t=s.amount*s.term/100;return out(['Short strategy','Term strategy','Term minus short'],[sh,t,t-sh],[['Break-even future rate',(2*s.term-s.short).toFixed(2)+'%','Price-only comparison'],['Availability risk','Not priced by this formula','Refinancing can fail, not merely become expensive']],`Term funding costs ${m(t-sh)} more than the short strategy under this scenario. Certainty can have value even when expected interest cost is higher.`);}});
 add({id:'ftp',stage:'03 · Pricing the balance sheet',name:'Funds transfer pricing',title:'The lending desk should see the funding risk it creates.',intro:'Build a matched-maturity internal funding charge and calculate a loan contribution after expected credit loss.',inputs:[a('loan','Loan balance',10,500,10,100),a('yield','Customer loan yield',2,12,.25,6,'%'),a('base','Matched-maturity reference rate',0,8,.25,3.5,'%'),a('liquidity','Liquidity and term premium',0,3,.1,1,'%'),a('option','Option / contingent-liquidity charge',0,2,.1,.3,'%')],challenge:'Raise the liquidity premium. Does the customer loan still appear attractive?',formula:'FTP = reference rate + liquidity premium + option charge\nContribution = balance × (loan yield − FTP − expected loss rate)',simple:'Funds transfer pricing allocates the cost and benefit of funding to the business creating it. A long-dated loan should not look profitable merely because today’s overnight money is cheap. Internal payments redistribute profit; they do not create group profit.',scope:'Expected credit loss charge fixed at 0.5% annually. No operating cost, capital charge, tax or behavioural optionality valuation. Components are illustrative internal pricing inputs, not regulatory tariff rates.',compute(s){const ftp=s.base+s.liquidity+s.option,con=s.loan*(s.yield-ftp-.5)/100;return out(['Loan interest','FTP expense','Contribution'],[s.loan*s.yield/100,s.loan*ftp/100,con],[['FTP rate',ftp.toFixed(2)+'%','Match tenor, currency and liquidity characteristics'],['Credit loss charge',m(s.loan*.005),'Separate from treasury funding cost'],['Internal versus group','Internal charge reallocates earnings','Do not count it twice at group level']],`The loan contributes ${m(con)} after the selected FTP and expected-loss charge. An apparently high customer yield can still leave a weak margin.`);}});
 add({id:'buffer-carry',stage:'03 · Pricing the balance sheet',name:'Liquidity buffer carry and opportunity cost',title:'A liquidity buffer is useful insurance with a carrying cost.',intro:'Compare a low-yield liquid buffer with the funding used to hold it and the alternative loan return.',inputs:[a('buffer','Liquid buffer',10,300,10,100),a('asset','Buffer yield',0,8,.25,3.5,'%'),a('funding','Funding cost',0,10,.25,4.5,'%'),a('loan','Alternative loan yield',0,12,.25,6,'%')],challenge:'Reduce the buffer to improve carry. What protection are you giving up?',formula:'Net buffer carry = buffer × (asset yield − funding cost)\nGross opportunity cost = buffer × (loan yield − asset yield)',simple:'Liquidity earns its value when ordinary funding disappears. Carry is visible in earnings every day; the benefit is often visible only in stress. Treasury needs both a cost view and a resilience view.',scope:'One-year simple interest, fixed balances, no credit losses or capital differences. Gross loan opportunity cost is not a risk-adjusted investment recommendation. Buffer adequacy is assessed in stress lessons.',compute(s){const carry=s.buffer*(s.asset-s.funding)/100,opp=s.buffer*(s.loan-s.asset)/100;return out(['Asset income','Funding expense','Net carry'],[s.buffer*s.asset/100,s.buffer*s.funding/100,carry],[['Gross opportunity cost',m(opp),'Before loan losses, capital and liquidity costs'],['Buffer principal',m(s.buffer),'Availability and eligibility still need testing']],`The buffer carries at ${m(carry)} per year. Its risk-management value cannot be judged from this income figure alone.`);}});
 add({id:'hqla',stage:'04 · Regulatory liquidity measures',name:'HQLA, haircuts and composition',title:'A security’s market value is not automatically its usable buffer value.',intro:'Combine Level 1 and Level 2A assets and apply the standard simplified haircut and composition cap.',inputs:[a('l1','Eligible Level 1 assets',0,200,10,80),a('l2','Eligible Level 2A assets',0,200,10,60),a('enc','Encumbered share of both pools',0,100,5,10,'%')],challenge:'Keep buying Level 2A while Level 1 stays fixed. Does recognised HQLA keep rising?',formula:'Usable L1 = L1 × (1−encumbrance)\nUsable L2A = L2A × (1−encumbrance) × 85%\nRecognised HQLA = usable L1 + min(usable L2A, 2/3 × usable L1)',simple:'Liquid assets must be eligible and available to monetise. Haircuts recognise value risk. Composition limits prevent a buffer from relying excessively on less liquid categories. An asset pledged elsewhere cannot be counted as freely available.',scope:'Basel Level 2A 15% haircut and 40% aggregate Level 2 limit, with no Level 2B and no secured-financing unwind adjustments. Assumes all remaining assets satisfy operational and eligibility criteria. UK application and firm-specific treatment require the applicable rules.',sources:[R.lcr,R.pra],compute(s){const l1=s.l1*(1-s.enc/100),l2=s.l2*(1-s.enc/100)*.85,allowed=Math.min(l2,l1*2/3);return out(['Usable Level 1','Recognised L2A','Total HQLA'],[l1,allowed,l1+allowed],[['L2A after haircut',m(l2),'Before composition cap'],['L2A excluded by cap',m(l2-allowed),'No benefit from excess composition'],['Encumbrance',s.enc+'%','Removed before haircut / cap']],`Recognised HQLA is ${m(l1+allowed)}. Extra Level 2A stops helping once the composition limit binds.`);}});
 add({id:'lcr',stage:'04 · Regulatory liquidity measures',name:'LCR and inflow cap',title:'A bank cannot rely entirely on expected receipts to survive stress.',intro:'Build the 30-day liquidity coverage ratio using supplied eligible HQLA and stressed flows.',inputs:[a('hqla','Eligible HQLA after all adjustments',0,200,5,90),a('out','Stressed 30-day outflows',5,200,5,100),a('inflow','Eligible stressed inflows',0,200,5,40)],challenge:'Raise inflows beyond 75% of outflows. What stops changing?',formula:'Net outflows = outflows − min(inflows, 75% × outflows)\nLCR = HQLA / net outflows',simple:'The LCR compares a usable liquid buffer with a prescribed short-term stress requirement. The inflow cap leaves a minimum need for a buffer even if customers are expected to pay substantial amounts into the bank.',scope:'General Basel 75% cap and 100% minimum in normal conditions; special exemptions omitted. Supplied flows already incorporate applicable regulatory categories and rates. Buffers are intended to be usable in stress; a sub-100% ratio is not an automatic statement of failure or insolvency.',sources:[R.lcr,R.pra],compute(s){const infl=Math.min(s.inflow,.75*s.out),net=s.out-infl,r=s.hqla/net;return out(['HQLA','Net outflows','Buffer surplus'],[s.hqla,net,s.hqla-net],[['Recognised inflows',m(infl),'75% cap in this general case'],['Excluded inflows',m(s.inflow-infl),'Do not further reduce denominator'],['Normal-condition benchmark','100%','Regulatory context, not internal risk appetite']],`LCR is ${p(r)}. An adequate aggregate ratio does not prove that every currency, entity or hour has enough cash.`,[['LCR',p(r)],['Net outflows',m(net)],['Surplus to 100%',m(s.hqla-net)]]);}});
 add({id:'nsfr',stage:'04 · Regulatory liquidity measures',name:'NSFR and stable funding',title:'Long-lived assets need funding that is likely to remain available.',intro:'Apply selected illustrative stability weights to a balanced simplified bank.',inputs:[a('loans','Long-term loans',100,500,25,300),a('deposits','Retail deposits',50,400,25,200),a('term','Term wholesale funding',0,200,10,80),a('stable','Deposit ASF weight assumption',50,100,5,90,'%')],challenge:'Replace short wholesale funding with term funding. What happens to stable funding?',formula:'ASF = equity + term debt × 100% + deposits × selected ASF\nRSF = long loans × 85% + excess cash × 0%\nNSFR = ASF / RSF',simple:'NSFR looks beyond a short stress window to structural funding stability. Not all liabilities are equally reliable and not all assets require the same amount of stable funding. The ratio translates those differences into weighted amounts.',scope:'Equity £40m. Residual financing is short wholesale with assumed ASF 0%; excess funding held as cash with RSF 0%. Term debt assumed remaining maturity at least one year. Loan RSF 85% is a selected qualifying example, not universal; deposit weight adjustable for teaching. Omits derivatives, encumbrance, commitments and many Basel categories.',sources:[R.nsfr,R.pra],compute(s){const asf=40+s.term+s.deposits*s.stable/100,rsf=s.loans*.85,gap=s.loans-40-s.term-s.deposits;return out(['ASF','RSF','Stable surplus'],[asf,rsf,asf-rsf],[['Short wholesale residual',m(Math.max(0,gap)),'Assumed ASF 0%'],['Excess cash',m(Math.max(0,-gap)),'Keeps the simplified balance sheet balanced'],['NSFR',p(asf/rsf),'Basel benchmark at least 100%']],`NSFR is ${p(asf/rsf)}. It complements the LCR; neither ratio replaces a dated cash forecast.`,[['NSFR',p(asf/rsf)],['ASF',m(asf)],['RSF',m(rsf)]]);}});
 add({id:'intraday',stage:'05 · Collateral and payment risk',name:'Intraday liquidity and payment timing',title:'Enough cash at closing time may be too late for a morning payment.',intro:'Move a major receipt before or after the first payment and inspect the intraday minimum.',inputs:[a('cash','Opening settlement cash',0,80,5,20),a('payment','Morning payment',0,100,5,50),a('receipt','Customer receipt',0,100,5,50),sel('timing','Receipt timing',[['early','Before the morning payment'],['late','After the morning payment']],'late')],challenge:'Keep daily net cash flow unchanged and delay the receipt.',formula:'Running balance = opening cash + cumulative settled receipts − payments\nPeak liquidity need = max(0, −minimum running balance)',simple:'Payment systems operate to deadlines. Cash arriving after an obligation falls due cannot fund that earlier payment. Treasury monitors peak usage, timed obligations, available credit and settlement queues, not just the end-of-day balance.',scope:'Three snapshots: opening, first event, second event. No payment netting, credit lines or queues; negative projected balance is unmet funding need.',sources:[R.intra,R.liq],compute(s){const values=[s.cash,s.cash+(s.timing==='early'?s.receipt:-s.payment),s.cash+s.receipt-s.payment],need=Math.max(0,-Math.min(...values));return out(['Opening','First event','Closing'],values,[['Peak funding gap',m(need),'Occurs before daily flows fully settle'],['Receipt order',s.timing,'Changes timing, not final cash']],`Closing cash is ${m(values[2])}, but the peak funding need is ${m(need)}. Payment timing creates risk even when daily net flows look balanced.`,[['Closing cash',m(values[2])],['Minimum balance',m(Math.min(...values))],['Peak gap',m(need)]]);}});
 add({id:'collateral',stage:'05 · Collateral and payment risk',name:'Repo, haircuts and encumbrance',title:'Collateral generates funding only to the extent it is eligible and available.',intro:'Calculate cash capacity from a security pool and see how haircuts and existing pledges reduce it.',inputs:[a('pool','Security market value',10,300,10,100),a('pledged','Already encumbered share',0,100,5,30,'%'),a('haircut','Funding haircut',0,50,5,10,'%'),a('price','Market-price fall',0,40,5,10,'%')],challenge:'Raise the haircut during a price fall. How quickly does funding capacity shrink?',formula:'Available collateral = pool × (1−encumbrance) × (1−price fall)\nCash capacity = available collateral × (1−haircut)',simple:'Repo converts eligible collateral into secured funding but leaves the security encumbered and creates a repayment obligation. The same asset cannot simultaneously fund several lenders or be treated as freely saleable in every contingency action.',scope:'Single collateral pool, immediate eligibility and settlement, no lender limit or market closure. Haircut is illustrative. Capacity is potential borrowing, not an inflow until a transaction settles.',sources:[R.liq,R.boe],compute(s){const av=s.pool*(1-s.pledged/100)*(1-s.price/100),cap=av*(1-s.haircut/100);return out(['Available value','Haircut deduction','Cash capacity'],[av,av-cap,cap],[['Encumbered starting value',m(s.pool*s.pledged/100),'Unavailable to this funding action'],['Repayment obligation',m(cap),'Borrowing is not an asset sale']],`The ${m(s.pool)} pool supports ${m(cap)} of new cash in this scenario. Eligibility, operational readiness and settlement time can reduce usable capacity further.`);}});
 add({id:'margin-calls',stage:'05 · Collateral and payment risk',name:'Margin calls and liquidity spirals',title:'A good hedge can still demand cash during stress.',intro:'Combine a cash variation-margin call with a haircut-driven repo top-up.',inputs:[a('dv01','Hedge loss per bp',0,.5,.01,.1,'£m/bp'),a('shock','Adverse rate shock',0,300,10,100,'bp'),a('repo','Cash borrowed on repo',0,200,10,80),a('haircut','New repo haircut',5,40,5,20,'%')],challenge:'Keep the hedge’s economic purpose unchanged and increase the collateral haircut.',formula:'VM cash call = DV01 × adverse bp shock\nInitial collateral = repo cash / 95%\nExtra collateral value = max(repo cash/(1−new haircut) − initial collateral,0)',simple:'A hedge may protect long-run value while generating an immediate cash margin call. Repo lenders can also demand more collateral when haircuts rise. Selling assets to meet calls can depress prices and create further calls.',scope:'Linear adverse hedge move, VM paid fully in cash, repo initially at 5% haircut with unchanged collateral price. Repo top-up is collateral market value, not necessarily cash; chart keeps the two needs separate. No dynamic fire-sale feedback.',sources:[R.liq,R.pra],compute(s){const vm=s.dv01*s.shock,extra=Math.max(0,s.repo/(1-s.haircut/100)-s.repo/.95);return out(['Cash VM','Collateral top-up'],[vm,extra],[['Cash need',m(vm),'Variation margin'],['Additional securities',m(extra),'Market value; separate resource from cash'],['Liquidity planning','Do not net these against unrealised hedge benefits','Availability and timing matter']],`This scenario needs ${m(vm)} cash plus ${m(extra)} additional collateral value. A positive economic hedge benefit elsewhere does not settle either call.`);}});
 add({id:'nii',stage:'06 · Interest rates and investment risk',name:'Repricing gaps and NII',title:'Rate changes affect earnings when assets and funding reset at different speeds.',intro:'Compare the one-year income impact of asset and liability repricing fractions.',inputs:[a('assets','Interest-earning assets',100,1000,50,600),a('liabilities','Interest-bearing funding',100,1000,50,550),a('af','Asset share repricing immediately',0,100,5,40,'%'),a('lf','Liability share repricing immediately',0,100,5,80,'%'),a('shock','Parallel rate change',-3,5,.25,2,'percentage points')],challenge:'Make liabilities reprice faster than assets in a rising-rate scenario.',formula:'ΔNII = (assets × repricing share − liabilities × repricing share) × rate change',simple:'A loan’s final maturity and its next rate reset are different dates. Treasury looks at when interest income and expense change, including customer pass-through and floors. Funding can become more expensive before fixed-rate assets earn more.',scope:'Instantaneous repricing for selected shares, full-year effect, constant balances and full pass-through. No floors, basis differences, new business or tax. See IRRBB Lab for richer scenarios.',sources:[R.ir],compute(s){const ai=s.assets*s.af/100*s.shock/100,li=s.liabilities*s.lf/100*s.shock/100;return out(['Income change','Expense change','ΔNII'],[ai,li,ai-li],[['Repricing asset balance',m(s.assets*s.af/100),'Full-year change'],['Repricing funding balance',m(s.liabilities*s.lf/100),'Full-year change']],`Annual NII changes by ${m(ai-li)}. A large fixed-rate asset book can lose earnings when its funding resets upward first.`);}});
 add({id:'eve',stage:'06 · Interest rates and investment risk',name:'Duration, DV01 and economic value',title:'Stable near-term earnings can coexist with a large economic-value loss.',intro:'Compare asset and liability modified durations and add a signed hedge DV01.',inputs:[a('assets','Asset present value',100,1000,50,600),a('da','Asset modified duration',0,10,.5,5,'years'),a('liabilities','Liability present value',100,1000,50,550),a('dl','Liability modified duration',0,10,.5,2,'years'),a('hedge','Hedge DV01 (positive = loses on rise)',-.5,.5,.01,-.1,'£m/bp'),a('shock','Parallel rate shock',-300,300,25,200,'bp')],challenge:'Reduce NII exposure in one lesson, then ask whether the value exposure would also disappear.',formula:'Net DV01 = assets × durationA / 10,000 − liabilities × durationL / 10,000 + hedge DV01\nΔEVE ≈ −net DV01 × shock in bp',simple:'Economic value discounts the entire future cash-flow stream. Longer-duration assets lose more value when yields rise, while a fall in liability value offsets part of the loss. The earnings and value perspectives answer different questions.',scope:'First-order duration approximation, parallel shock, supplied PVs and modified durations. No convexity, curve reshaping, behavioural recalibration or regulatory EVE exclusions. Large shocks reduce approximation accuracy.',sources:[R.ir],compute(s){const av=s.assets*s.da/10000,lv=s.liabilities*s.dl/10000,net=av-lv+s.hedge;return out(['Asset ΔPV','Liability ΔPV','ΔEVE'],[-av*s.shock,-lv*s.shock,-net*s.shock],[['Net DV01',m(net)+'/bp','Positive means value loss on a rise'],['Hedge contribution',m(-s.hedge*s.shock),'Signed separately'],['Method','Linear duration','Not full repricing']],`Net DV01 is ${m(net)}/bp, producing estimated ΔEVE ${m(-net*s.shock)}. Earnings stability alone does not establish low value risk.`,[['Net DV01',m(net)+'/bp'],['ΔEVE',m(-net*s.shock)],['Hedge ΔPV',m(-s.hedge*s.shock)]]);}});
 add({id:'basis',stage:'06 · Interest rates and investment risk',name:'Basis risk and imperfect hedges',title:'Matching the reset date does not make two interest rates identical.',intro:'Let the loan reference rate and the funding reference rate move by different amounts.',inputs:[a('balance','Matched asset and funding balance',10,500,10,100),a('assetMove','Asset reference-rate change',-3,5,.25,1,'percentage points'),a('fundMove','Funding reference-rate change',-3,5,.25,2,'percentage points'),a('hedge','Basis hedge fraction',0,100,5,50,'%')],challenge:'Apply equal shocks to both rates, then separate their movements.',formula:'Unhedged ΔNII = balance × (asset-rate change − funding-rate change)\nResidual = unhedged ΔNII × (1−hedge fraction)',simple:'Loans, deposits and hedges may reference different benchmarks or customer pricing rules. Even a matched repricing schedule can leave basis exposure when those rates do not move together.',scope:'Full-year simple interest, equal balances and a perfect hedge of the selected basis fraction. No hedge cost, credit valuation or changing customer beta.',sources:[R.ir],compute(s){const raw=s.balance*(s.assetMove-s.fundMove)/100,res=raw*(1-s.hedge/100);return out(['Before hedge','Hedge offset','Residual ΔNII'],[raw,-raw*s.hedge/100,res],[['Rate divergence',(s.assetMove-s.fundMove).toFixed(2)+' pp','Spread between two changes'],['Unmodelled risks','Hedge cost and counterparty exposure','A hedge introduces its own dependencies']],`The residual earnings impact is ${m(res)}. Matching notional and maturity cannot remove a mismatch between reference rates.`);}});
 add({id:'prepayment',stage:'06 · Interest rates and investment risk',name:'Prepayment and reinvestment risk',title:'Customers may return your best-yielding assets when replacement yields are lowest.',intro:'Repay part of a fixed-rate loan book early and reinvest the principal at the new yield.',inputs:[a('loans','Fixed-rate loan book',50,500,25,200),a('coupon','Existing loan yield',1,10,.25,6,'%'),a('prepay','Share prepaid immediately',0,100,5,30,'%'),a('newYield','Reinvestment yield',0,10,.25,3,'%')],challenge:'Increase prepayments when reinvestment yields are below the original coupon.',formula:'Income after prepayment = balance × [(1−prepay) × coupon + prepay × new yield]',simple:'Borrower choices change the timing of cash flows. When rates fall, refinancing can return principal just when treasury would prefer to keep the higher coupon. Behavioural options can change both NII and duration.',scope:'Immediate prepayment, full reinvestment for one year, unchanged principal and no penalties, fees or credit loss. Prepayment probability is selected, not estimated from interest rates.',sources:[R.ir],compute(s){const old=s.loans*s.coupon/100,now=s.loans*((1-s.prepay/100)*s.coupon+s.prepay/100*s.newYield)/100;return out(['Original income','New income','Income change'],[old,now,now-old],[['Principal returned',m(s.loans*s.prepay/100),'Cash improves immediately'],['Reinvestment spread',(s.newYield-s.coupon).toFixed(2)+' pp','Earnings can fall despite the cash receipt']],`Prepayment releases ${m(s.loans*s.prepay/100)} principal but changes annual income by ${m(now-old)}.`);}});
 add({id:'investment-book',stage:'06 · Interest rates and investment risk',name:'Investment securities and spread risk',title:'A liquid bond can still lose value through rates or credit spreads.',intro:'Shock a bond portfolio’s risk-free yield and credit spread separately.',inputs:[a('value','Bond market value',10,300,10,100),a('duration','Modified / spread duration assumption',0,10,.5,4,'years'),a('rates','Risk-free rate move',-200,300,25,100,'bp'),a('spread','Credit-spread widening',0,500,25,100,'bp')],challenge:'Hedge the risk-free rate move mentally. Which part of the loss remains?',formula:'Rate ΔPV ≈ −value × duration × rate shock\nSpread ΔPV ≈ −value × duration × spread shock',simple:'Treasury investments carry market and credit-spread risk alongside their liquidity role. A government-rate hedge may not protect a credit-spread widening. Accounting presentation affects where a change appears, but does not make economic risk disappear.',scope:'Linear pricing, same duration for rates and spreads, no default jump or convexity. No IFRS 9 classification or hedge-accounting calculation; accounting treatment requires separate eligibility assessment.',sources:[R.ir,R.liq],compute(s){const rate=-s.value*s.duration*s.rates/10000,sp=-s.value*s.duration*s.spread/10000;return out(['Rate change','Spread change','Total ΔPV'],[rate,sp,rate+sp],[['Rate-hedged residual',m(sp),'Spread risk survives a perfect rate hedge'],['Approximate new value',m(s.value+rate+sp),'First-order approximation only']],`The approximate loss combines ${m(rate)} from rates and ${m(sp)} from spreads. Liquidity classification does not imply zero price risk.`);}});
 add({id:'fx',stage:'07 · FX, counterparties and group liquidity',name:'FX exposure and natural hedges',title:'Currency matching matters before the group total is translated.',intro:'Offset foreign-currency receipts and payments, then hedge part of the residual.',inputs:[a('receipts','Foreign receipts translated at starting FX',0,200,10,100),a('payments','Foreign payments translated at starting FX',0,200,10,60),a('hedge','Residual exposure hedged',0,100,5,50,'%'),a('move','Foreign currency change versus GBP',-30,30,5,-10,'%')],challenge:'Match receipts and payments, then consider whether their settlement dates also match.',formula:'Net FX exposure = receipts − payments\nResidual ΔGBP ≈ net exposure × (1−hedge share) × FX percentage change',simple:'Natural hedges reduce exposure when cash flows use the same currency. Their dates and legal availability still matter. Translation of accounting balances, future transaction cash flows and long-run business competitiveness are related but different FX risks.',scope:'Same-date cash flows, starting GBP-equivalent amounts, linear spot change and a perfect forward hedge of the selected fraction. Excludes forward points, hedge cost and forecast uncertainty.',sources:[R.fx,R.liq],compute(s){const net=s.receipts-s.payments,raw=net*s.move/100,res=raw*(1-s.hedge/100);return out(['Unhedged change','Hedge offset','Residual change'],[raw,-raw*s.hedge/100,res],[['Net exposure at start',m(net),'Signed foreign-currency position'],['Unhedged share',p(1-s.hedge/100),'Applied to the residual after natural matching']],`Residual currency impact is ${m(res)}. Equal annual receipts and payments can still leave dated currency funding gaps.`);}});
 add({id:'fx-funding',stage:'07 · FX, counterparties and group liquidity',name:'FX swap funding and basis cost',title:'A currency hedge can conceal a refinancing dependency.',intro:'Estimate the cost of obtaining foreign currency via a short FX swap and compare it with direct term borrowing.',inputs:[a('amount','Foreign funding in GBP equivalent',10,300,10,100),a('rate','Base synthetic foreign funding rate',0,10,.25,4,'%'),a('basis','Additional basis / execution cost',0,300,25,75,'bp'),a('direct','Direct foreign term funding rate',0,12,.25,5.5,'%')],challenge:'Widen the basis while keeping the domestic funding rate unchanged.',formula:'Synthetic all-in rate = base synthetic foreign rate + basis cost / 100\nAnnual interest proxy = amount × rate',simple:'FX swaps exchange currencies now and reverse the exchange later. They can solve today’s currency need while creating a future repayment and rollover obligation. Basis and market access can deteriorate exactly when the foreign currency is most needed.',scope:'Input base rate already includes interest-rate differential / forward-point economics. Positive basis is defined here as added funding cost; market quote sign conventions vary. Simple cost comparison, not a no-arbitrage FX swap pricer.',sources:[R.fx,R.liq],compute(s){const synthetic=s.amount*(s.rate/100+s.basis/10000),direct=s.amount*s.direct/100;return out(['Swap funding','Direct term','Extra swap cost'],[synthetic,direct,synthetic-direct],[['Synthetic all-in rate',(s.rate+s.basis/100).toFixed(2)+'%','Explicit cost-sign convention'],['Rollover dependency','Swap maturity must be refinanced or repaid','Not captured by interest expense alone']],`Synthetic funding costs ${m(synthetic)} annually under these inputs, but continued availability is a separate risk.`);}});
 add({id:'settlement',stage:'07 · FX, counterparties and group liquidity',name:'Settlement risk and PvP',title:'Paying one currency before receiving the other can expose the full principal.',intro:'Compare principal-at-risk for non-PvP settlement with payment-versus-payment coverage.',inputs:[a('gross','Gross payable principal',10,300,10,100),a('net','Legally effective payment netting reduction',0,90,5,40,'%'),a('pvp','Remaining settlement using PvP',0,100,5,80,'%')],challenge:'Increase PvP coverage to 100%. Which risks still require management?',formula:'Net payable = gross × (1−netting share)\nNon-PvP principal at risk = net payable × (1−PvP coverage)',simple:'In an FX settlement failure, the amount at stake can be the currency principal already paid, not just the trade’s mark-to-market. PvP links the two currency payments, reducing principal risk while leaving funding, operational and replacement-cost risks to manage.',scope:'Assumes enforceable payment netting and effective PvP for the selected share. Exposure is a principal-risk amount, not expected loss, and excludes settlement timing duration and replacement-cost calculations.',sources:[R.fx],compute(s){const net=s.gross*(1-s.net/100),risk=net*(1-s.pvp/100);return out(['Gross payable','After netting','Non-PvP risk'],[s.gross,net,risk],[['PvP-covered principal',m(net-risk),'Conditional exchange of currencies'],['Residual risks','Liquidity, operations, replacement cost','Do not disappear with principal-risk mitigation']],`Non-PvP principal exposure is ${m(risk)}. Even full PvP coverage still needs sufficient currency liquidity at settlement.`);}});
 add({id:'counterparty',stage:'07 · FX, counterparties and group liquidity',name:'Treasury counterparty exposure',title:'A high-yield deposit at another bank is also a credit exposure.',intro:'Combine unsecured cash placement with positive derivative replacement value and effective collateral.',inputs:[a('cash','Unsecured placement',0,200,10,80),a('mtm','Positive derivative value',0,50,1,10),a('collateral','Eligible collateral against derivative',0,50,1,6),a('pd','One-year counterparty PD assumption',0,10,.25,1,'%'),a('lgd','Loss given default',0,100,5,60,'%')],challenge:'Collateralise the derivative fully. Does the unsecured cash placement become safe?',formula:'Current unsecured exposure = placement + max(derivative MTM − collateral,0)\nExpected-loss proxy = current exposure × PD × LGD',simple:'Treasury counterparties supply funding, hold deposits, settle currencies and provide hedges. Concentrating several roles in one institution can create a dependency larger than any one exposure measure suggests.',scope:'Current-exposure proxy only, same counterparty, collateral allocated only to the derivative. No PFE, wrong-way risk, settlement principal exposure, legal netting set calculation or SA-CCR. PD and LGD are illustrative.',sources:[R.liq,R.fx],compute(s){const der=Math.max(s.mtm-s.collateral,0),exp=s.cash+der,el=exp*s.pd*s.lgd/10000;return out(['Cash exposure','Derivative exposure','EL proxy'],[s.cash,der,el],[['Current total exposure',m(exp),'Not regulatory EAD'],['Unmodelled future exposure','PFE and wrong-way risk','Explore SA-CCR and XVA modules']],`Expected-loss proxy is ${m(el)}, while current unsecured exposure is ${m(exp)}. Collateral against a derivative does not automatically protect an unrelated cash placement.`);}});
 add({id:'trapped-cash',stage:'07 · FX, counterparties and group liquidity',name:'Trapped liquidity and legal entities',title:'Group cash cannot pay a bill if it cannot reach the entity that owes it.',intro:'Transfer part of surplus cash from one entity to another under a legal or operational transfer limit.',inputs:[a('local','Cash at entity A',0,100,5,20),a('other','Cash at entity B',0,100,5,80),a('need','Entity A payment due',0,150,5,70),a('transfer','B cash transferable before deadline',0,100,5,25,'%')],challenge:'Increase group cash at B while transferability is zero.',formula:'Accessible cash at A = local cash + B cash × transferable fraction\nLocal gap = max(payment − accessible cash,0)',simple:'Liquidity can be restricted by currency, entity, regulation, tax, collateral location or payment cut-offs. Treasury maps where cash is held and where obligations fall due; a consolidated total can hide local shortages.',scope:'One transfer from B to A, no B obligations, FX conversion or transfer cost. Transferability is a scenario input, not a legal opinion.',compute(s){const accessible=s.local+s.other*s.transfer/100,gap=Math.max(0,s.need-accessible);return out(['Group cash','Accessible at A','Local gap'],[s.local+s.other,accessible,gap],[['Transferred',m(s.other*s.transfer/100),'Only amounts available before the deadline'],['Remaining at B',m(s.other*(1-s.transfer/100)),'Not available for A’s selected payment']],`Group cash is ${m(s.local+s.other)}, but entity A still has a ${m(gap)} payment gap. Location matters as much as the total.`);}});
 add({id:'stress',stage:'08 · Stress, recovery and ALCO decisions',name:'Integrated liquidity stress',title:'A stress becomes dangerous when several cash demands arrive together.',intro:'Combine deposit runoff, failed refinancing and margin calls against cash and monetisable collateral.',inputs:[a('cash','Starting cash buffer',10,150,10,60),a('deposits','Deposit balance',100,500,25,300),a('run','Deposit runoff',0,40,2,10,'%'),a('roll','Rollover success on £50m debt',0,100,10,50,'%'),a('margin','Cash margin call',0,50,5,15),a('sell','Eligible unencumbered assets available to sell',0,100,10,40)],challenge:'Increase deposit runoff while reducing refinancing success. Are the effects additive?',formula:'Outflows = deposit runoff + unrefinanced debt + margin call\nResources = cash + asset-sale value × 90%\nHeadroom = resources − outflows',simple:'Idiosyncratic stress can drive customers away while market stress closes funding and lowers collateral values. Treasury must consider combined shocks and avoid assuming every action remains available simultaneously.',scope:'Single stress window, 10% asset-sale discount, all sales executable before obligations fall due. No cash receipts, tax, capital requirement or intraday delays. Selected assets are assumed separate from cash and unencumbered.',compute(s){const dep=s.deposits*s.run/100,debt=50*(1-s.roll/100),resources=s.cash+s.sell*.9,outflow=dep+debt+s.margin;return out(['Resources','Total calls','Headroom'],[resources,outflow,resources-outflow],[['Deposit outflow',m(dep),'Behavioural scenario'],['Unrolled debt',m(debt),'Maturity refinancing failure'],['Margin call',m(s.margin),'Cash payment'],['Sale proceeds',m(s.sell*.9),'After a 10% discount']],`Headroom is ${m(resources-outflow)} after combined shocks. Test action timing and market capacity before treating these sale proceeds as dependable.`);}});
 add({id:'reverse-stress',stage:'08 · Stress, recovery and ALCO decisions',name:'Reverse stress testing',title:'Start with failure, then find the deposit outflow that would cause it.',intro:'Calculate the withdrawal share that exhausts resources after fixed other calls.',inputs:[a('resources','Usable liquidity resources',10,200,10,80),a('other','Other fixed cash calls',0,150,10,30),a('deposits','Runnable deposits',50,500,25,250)],challenge:'Raise other cash calls. How much customer withdrawal can the bank now withstand?',formula:'Break-even withdrawal share = (resources − other calls) / runnable deposits',simple:'Ordinary stress testing asks what happens under a scenario. Reverse stress testing asks what combination of events would make the plan fail, then challenges whether that combination is plausible and what actions would prevent it.',scope:'Single period, linear withdrawals and fixed available resources. A threshold above 100% means all this deposit pool could leave without exhausting the modelled resources; a negative threshold means other calls already exceed resources. No probability is assigned.',compute(s){const room=s.resources-s.other,threshold=room/s.deposits;return out(['Usable resources','Other calls','Withdrawal room'],[s.resources,s.other,room],[['Break-even fraction',p(threshold),'Equality exhausts resources; greater runoff creates a gap'],['Interpretation',threshold<0?'Already short before withdrawals':threshold>1?'Beyond the full selected deposit pool':'Within the selected deposit pool','Not a forecast or breach probability']],`The break-even withdrawal share is ${p(threshold)}. The next task is to judge plausibility and identify credible preventive actions.`,[['Break-even runoff',p(threshold)],['Withdrawal room',m(room)],['Runnable deposits',m(s.deposits)]]);}});
 add({id:'contingency',stage:'08 · Stress, recovery and ALCO decisions',name:'Contingency funding and execution',title:'A funding action only helps if it settles before the cash is needed.',intro:'Test whether a secured funding action can close a dated liquidity gap.',inputs:[a('cash','Starting cash',0,100,5,20),a('payment','Day-2 payment',0,150,5,70),a('pool','Eligible collateral pool',0,150,10,80),a('lag','Action settlement day',1,5,1,3,'day'),a('haircut','Funding haircut',0,40,5,15,'%')],challenge:'Move action settlement from day 3 to day 1 without changing nominal capacity.',formula:'Action proceeds = collateral × (1−haircut)\nDay-2 headroom = cash + proceeds if settled by day 2 − payment',simple:'A contingency plan needs named owners, triggers, collateral readiness, tested settlement steps and realistic market capacity. An untested central-bank or market facility is not the same as cash already available.',scope:'One secured action using a unique collateral pool. Proceeds arriving on day 2 assumed before the payment deadline. No central-bank eligibility determination, stigma, borrowing limit or interest cost.',sources:[R.pra,R.boe,R.liq],compute(s){const proceeds=s.pool*(1-s.haircut/100),timely=s.lag<=2?proceeds:0;return out(['Action capacity','Timely proceeds','Day-2 headroom'],[proceeds,timely,s.cash+timely-s.payment],[['Settlement day',s.lag,'Capacity alone is insufficient'],['Later cash after payment',m(s.cash+proceeds-s.payment),'Does not cure a missed earlier deadline']],`Only ${m(timely)} arrives in time. Operational readiness determines whether the funding action actually protects the payment.`);}});
 add({id:'data',stage:'08 · Stress, recovery and ALCO decisions',name:'Data quality and model challenge',title:'A comfortable forecast can be an incomplete forecast.',intro:'Inject an omitted maturity, duplicate cash balance or stale collateral haircut into a liquidity report.',inputs:[a('cash','Actual cash',20,150,10,70),a('out','Actual obligations',20,150,10,80),a('collateral','Available collateral',0,100,10,40),sel('error','Reporting issue',[['none','Reconciled report'],['missing','£30m maturity omitted'],['duplicate','£20m cash counted twice'],['haircut','Stale 5% haircut instead of 20%']],'missing')],challenge:'Can a report show positive headroom while the reconciled position is negative?',formula:'True headroom = cash + collateral × 80% − obligations\nReported headroom changes only through the selected reporting error',simple:'Treasury risk depends on complete trade populations, correct dates, currency and entity tags, collateral status and reliable behavioural estimates. Reconciliation, independent challenge and ownership of exceptions turn a spreadsheet into a controlled decision process.',scope:'Three deliberately injected errors; not a full data-control framework. True haircut fixed at 20%. An omitted maturity cannot exceed actual obligations in the displayed report.',compute(s){const real=s.cash+s.collateral*.8-s.out,missing=s.error==='missing'?Math.min(30,s.out):0,reported=real+missing+(s.error==='duplicate'?20:0)+(s.error==='haircut'?s.collateral*.15:0);return out(['Reconciled','Reported','Overstatement'],[real,reported,reported-real],[['Issue',s.error,'Trace the source, do not overwrite the final total'],['Omitted obligation',m(missing),'Capped at actual obligations'],['Controls','Completeness, reconciliation, freshness, ownership','Independent review of assumptions']],`The report overstates headroom by ${m(reported-real)}. A dashboard is only as reliable as its underlying data and assumptions.`);}});
 add({id:'alco',stage:'09 · Treasury decision capstone',name:'ALCO balance-sheet decision lab',title:'Choose a funding plan—and defend its earnings, liquidity and value trade-offs.',intro:'Allocate a £1bn bank between cash, bonds and loans, then choose term funding and a rate hedge.',inputs:[a('buffer','Cash buffer allocation',50,250,10,100),a('bonds','Bond allocation',50,250,10,150),a('term','Term funding within £300m wholesale',0,300,25,150),a('hedge','Signed rate hedge DV01',-.5,.5,.025,-.1,'£m/bp'),a('run','Runoff on £600m deposits',0,30,2,10,'%'),a('shock','Rate increase for value scenario',0,300,25,200,'bp')],challenge:'Improve stressed liquidity without losing sight of earnings and duration. Explain the cost of your decision to ALCO.',formula:'Loans = 1,000 − cash − bonds; deposits 600 + wholesale 300 + equity 100 = assets\nNII = 6% loans + 4% bonds + 3% cash − 2% deposits − 5% term − 4% short debt\nStress headroom = cash + 90% bonds − runoff − 50% unrolled short debt − hedge VM\nNet DV01 = (4×loans + 3×bonds − 2×term)/10,000 + hedge',simple:'The Asset and Liability Committee (ALCO) considers the whole balance sheet. More liquid assets can lower earnings. Longer funding can reduce rollover risk but cost more. A hedge changes economic value and may create collateral demands. A defensible decision makes those trade-offs explicit.',scope:'Synthetic balanced £1bn bank. Deposits assumed zero duration here; term debt duration 2, bonds 3, loans 4. Stress assumes 50% short-debt rollover, bond sale at 10% discount, no credit losses and immediate actions. Hedge VM = max(hedge DV01 × rate rise,0); gains are not assumed immediately available. ΔEVE is a pre-sale linear snapshot. No regulatory ratio or optimal portfolio is claimed; NII excludes hedge carry, valuation changes and other costs.',sources:[R.liq,R.ir,R.pra],compute(s){const loans=1000-s.buffer-s.bonds,short=300-s.term,nii=loans*.06+s.bonds*.04+s.buffer*.03-600*.02-s.term*.05-short*.04,vm=Math.max(0,s.hedge*s.shock),head=s.buffer+s.bonds*.9-600*s.run/100-short*.5-vm,dv=(4*loans+3*s.bonds-2*s.term)/10000+s.hedge,eve=-dv*s.shock;return out(['Annual NII','Stress headroom','ΔEVE'],[nii,head,eve],[['Loans / cash / bonds',`${m(loans)} / ${m(s.buffer)} / ${m(s.bonds)}`,'Assets total £1,000m'],['Short wholesale',m(short),'50% cannot be refinanced in stress'],['Deposit outflow',m(600*s.run/100),'Selected behavioural stress'],['Hedge cash VM',m(vm),'Adverse hedge move only'],['Asset sale loss',m(s.bonds*.1),'Not included in baseline NII or pre-sale ΔEVE'],['Net DV01',m(dv)+'/bp','First-order value risk']],`Your plan earns ${m(nii)} baseline annual NII, leaves ${m(head)} stressed liquidity headroom and has estimated ΔEVE ${m(eve)}. Defend the assumptions as well as the headline results.`);}});
 add({id:'risk-appetite',stage:'08 · Stress, recovery and ALCO decisions',name:'Risk appetite and early warnings',title:'An early warning is useful only if it leaves time to act.',intro:'Forecast when a declining cash buffer crosses a management warning and a lower internal limit.',inputs:[a('cash','Opening usable liquidity',30,150,10,100),a('burn','Daily stressed net cash use',1,10,1,4),a('limit','Internal minimum buffer',0,50,5,20),a('lead','Desired warning lead time',1,10,1,5,'days')],challenge:'Double the rate of cash use. Does an unchanged warning level still provide enough reaction time?',formula:'Warning level = internal minimum + daily cash use × desired lead time\nDays to lower limit = max((opening cash − minimum)/daily cash use,0)',simple:'Risk appetite translates the board’s tolerance into measurable limits, warning indicators and escalation. An amber indicator should initiate investigation and preparation before a hard limit is crossed; a limit without ownership and an action plan offers little protection.',scope:'Linear cash decline over 30 days; warning level calculated to give the selected lead time. Internal levels are illustrative and are not PRA or Basel thresholds. Starting below a trigger means escalation is already due. No probabilistic forecast.',compute(s){const warning=s.limit+s.burn*s.lead,days=Math.max(0,(s.cash-s.limit)/s.burn),status=s.cash<=s.limit?'Limit reached':s.cash<=warning?'Warning reached':'Above warning';return {stats:[['Current status',status],['Warning level',m(warning)],['Time to limit',days.toFixed(1)+' days']],series:[{name:'Projected liquidity',color:'#285e46',data:path(s.cash,s.burn)},{name:'Warning',color:'#b68744',data:[[0,warning],[30,warning]]},{name:'Internal minimum',color:'#a45151',data:[[0,s.limit],[30,s.limit]]}],xlabel:'Day',headers:['Trigger','Value','Action'],rows:[['Warning',m(warning),'Investigate, notify owners and prepare actions'],['Internal minimum',m(s.limit),'Escalate through the agreed governance process'],['Lead time',s.lead+' days','Valid only under the assumed cash-use rate']],explanation:`${status}. The selected warning is ${m(warning)}, designed to leave ${s.lead} days before the lower limit under this cash-use assumption.`};}});
 add({id:'ilaap',stage:'08 · Stress, recovery and ALCO decisions',name:'ILAAP and evidence of adequacy',title:'Liquidity adequacy is an argument supported by evidence, not one ratio.',intro:'Compare resources with institution-specific, market-wide and combined scenario needs.',inputs:[a('cash','Immediately usable resources',10,150,10,60),a('action','Additional action capacity',0,100,10,40),a('ready','Action executable in time',0,100,10,50,'%'),a('firm','Institution-specific stress need',10,150,10,70),a('market','Market-wide stress need',10,150,10,60),a('combined','Combined stress need',10,200,10,100)],challenge:'Make the standalone scenarios pass while the combined scenario still shows a shortfall.',formula:'Credible resources = immediate resources + action capacity × executable share\nScenario headroom = credible resources − scenario need',simple:'The Internal Liquidity Adequacy Assessment Process connects the business model, risk identification, stress testing, resources, funding plan, contingency actions and governance. The document records that assessment, but the process must inform actual decisions and be reviewed as conditions change.',scope:'Three independently specified scenario requirements and a single disjoint additional resource pool. This is a diagnostic illustration, not an ILAAP scoring system or regulatory buffer formula. Combined needs need not equal the sum of the other scenarios because assumptions and overlap differ. Regulatory ratios, intraday, currency and entity risks still require separate assessment.',sources:[R.pra,R.liq],compute(s){const resources=s.cash+s.action*s.ready/100,needs=[s.firm,s.market,s.combined],head=needs.map(x=>resources-x);return out(['Firm headroom','Market headroom','Combined headroom'],head,[['Credible resources',m(resources),'Additional pool is separate from immediate cash'],['Unready action capacity',m(s.action*(1-s.ready/100)),'Excluded until execution is credible'],['Evidence needed','Risk map, stress assumptions, collateral tests, ownership','Adequacy is not inferred from this chart alone']],`The weakest scenario headroom is ${m(Math.min(...head))}. Passing standalone cases does not establish resilience to a combined event.`,[['Credible resources',m(resources)],['Worst headroom',m(Math.min(...head))],['Cases with a gap',head.filter(x=>x<0).length+' / 3']]);}});
 TRISK_LESSONS.sort((a,b)=>a.stage.localeCompare(b.stage));
})();
